@Scheduled(fixedDelay = 5000)
@Transactional
fun autoCompleteExpiredVerifications() {
  val pending = repo.findAllByStatus(PENDING)
  val now = LocalDateTime.now()
  pending.forEach { v ->
    val elapsed = Duration.between(v.enteredAt, now).seconds
    if (elapsed >= requiredStaySeconds) {
      v.status = VERIFIED
      v.stayDurationSeconds = elapsed.toInt()
      repo.save(v)
    }
  }
}

